import React, { useEffect, useState } from 'react';

const lines = [
  ['name', '=', '"Chetanya Makkar"'],
  ['major', '=', '"Computer Science"'],
  ['minor', '=', '"Computational Finance"'],
  ['gpa', '=', '3.76'],
  ['school', '=', '"University of Maryland"'],
];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState([]);
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);

  useEffect(() => {
    if (lineIndex < lines.length) {
      const lineParts = lines[lineIndex];
      const fullLine = lineParts.join(' ');
      if (charIndex < fullLine.length) {
        const timeout = setTimeout(() => {
          const current = fullLine.slice(0, charIndex + 1);
          setCurrentLine([current]);
          setCharIndex((i) => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines((prev) => [...prev, [...lineParts]]);
          setCurrentLine([]);
          setCharIndex(0);
          setLineIndex((i) => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine([]);
        setCharIndex(0);
        setLineIndex(0);
        setLoop((l) => l + 1);
      }, 2500);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  const renderLine = (parts, isTyping = false) => {
    const [key, equalSign, value] = parts;
    return (
      <div
        className={`whitespace-pre w-fit ${
          isTyping ? 'border-r-2 border-gray-400 animate-blink' : ''
        }`}
      >
        <span className="text-[#9CDCFE]">{key}</span>
        <span className="text-[#d4d4d4]"> {equalSign} </span>
        <span className={String(value).startsWith('"') ? 'text-[#ce9178]' : 'text-[#b5cea8]'}>
          {value}
        </span>
      </div>
    );
  };

  return (
    <div className="bg-[#1e1e1e] text-[#d4d4d4] min-h-screen flex items-center justify-center font-mono text-xl p-6">
      <div className="space-y-2 text-left">
        {typedLines.map((parts, idx) => (
          <div key={`line-${loop}-${idx}`}>{renderLine(parts)}</div>
        ))}
        {lineIndex < lines.length && currentLine.length > 0 && (
          <div>{renderLine(lines[lineIndex], true)}</div>
        )}
      </div>
    </div>
  );
}
